import{_ as e,o as d,c as a,a6 as o}from"./chunks/framework.DIp0zHSV.js";const m=JSON.parse('{"title":"Coming from CB-LCARS","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/cb-lcars-migration.md","filePath":"getting-started/cb-lcars-migration.md","lastUpdated":1792162559000}'),r={name:"getting-started/cb-lcars-migration.md"};function c(n,t,l,s,i,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="coming-from-cb-lcars" tabindex="-1">Coming from CB-LCARS <a class="header-anchor" href="#coming-from-cb-lcars" aria-label="Permalink to &quot;Coming from CB-LCARS&quot;">​</a></h1><p>LCARdS originates from, and supersedes, the <a href="https://github.com/snootched/cb-lcars" target="_blank" rel="noreferrer">CB-LCARS</a> project.</p><p>CB-LCARS was based on <a href="https://github.com/custom-cards/button-card" target="_blank" rel="noreferrer">Custom Button Card</a>; LCARdS is built from scratch with Lit and needs no other custom cards.</p><p>Most features have been ported to LCARdS. Use the table to find the LCARdS equivalent of each CB-LCARS card or feature.</p><div class="tip custom-block"><p class="custom-block-title">You can run both simultaneously</p><p>CB-LCARS and LCARdS can coexist while you transition. All new features and fixes will be made in LCARdS only going forward.</p><p>The configuration formats differ, so card configs don&#39;t carry over directly.</p></div><h2 id="feature-comparison" tabindex="-1">Feature Comparison <a class="header-anchor" href="#feature-comparison" aria-label="Permalink to &quot;Feature Comparison&quot;">​</a></h2><p>✅ Present | ❌ Not present | ⚠️ Partial</p><table tabindex="0"><thead><tr><th>Feature</th><th style="text-align:center;">CB-LCARS</th><th style="text-align:center;">LCARdS</th><th>Notes</th></tr></thead><tbody><tr><td>Buttons</td><td style="text-align:center;">✅ <code>cb-lcars-button-card</code></td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>Built-in <code>preset</code> collection provides the standard LCARS button styles, which are completely configurable.</td></tr><tr><td>Multi-Segment Buttons</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>Allows complex button designs (known as <code>component</code>) to be used as advanced multi-segment/multi-touch controls, configured via <code>segments</code>.</td></tr><tr><td>DPAD</td><td style="text-align:center;">✅ <code>cb-lcars-dpad-card</code></td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>First advanced button to use the <code>component</code> feature of <code>lcards-button</code>.</td></tr><tr><td>ALERT</td><td style="text-align:center;">⚠️ background animation</td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>Promoted to a button card component: allows full interactive configuration.</td></tr><tr><td>Labels</td><td style="text-align:center;">✅ <code>cb-lcars-label-card</code></td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>Label functionality is available via <code>lcards-button</code>. Additional presets available for text labels with or without decoration.</td></tr><tr><td>Elbows</td><td style="text-align:center;">✅ <code>cb-lcars-elbow-card</code></td><td style="text-align:center;">✅ <code>lcards-elbow</code></td><td>Equivalent in LCARdS: enhanced with more corner styles (e.g. straight cut with configurable angles).</td></tr><tr><td>Double Elbows</td><td style="text-align:center;">✅ <code>cb-lcars-double-elbow-card</code></td><td style="text-align:center;">✅ <code>lcards-elbow</code></td><td>Double Elbow functionality is now consolidated into a single unified <code>lcards-elbow</code> card.</td></tr><tr><td>Sliders</td><td style="text-align:center;">✅ <code>cb-lcars-multimeter-card</code></td><td style="text-align:center;">✅ <code>lcards-slider</code></td><td>Completely replacing the former multimeter card. Vastly improved: configurable direction, inversion, display min/max, control min/max, and more.</td></tr><tr><td>Cascade Data Grid</td><td style="text-align:center;">⚠️ background animation</td><td style="text-align:center;">✅ <code>lcards-data-grid</code></td><td>CB-LCARS provided a decorative-only version as a background animation. <code>lcards-data-grid</code> is a full-featured grid that can show real entity data, text, etc. Decorative mode is still available.</td></tr><tr><td>Text</td><td style="text-align:center;">✅ <code>cb-lcars-text-card</code></td><td style="text-align:center;">✅ <code>lcards-button</code></td><td>Text-only button presets, or text fields on any card.</td></tr><tr><td>Picard-style controls</td><td style="text-align:center;">✅ <code>cb-lcars-picard-card</code></td><td style="text-align:center;">✅ <code>lcards-elbow</code>, <code>lcards-slider</code></td><td>Segmented (double) elbows and frames on <code>lcards-elbow</code>; the <code>picard</code> slider component with the <code>picard-gauge-vertical</code> preset; <code>filled</code> and <code>outline</code> button presets.</td></tr><tr><td>Layouts</td><td style="text-align:center;">⚠️ <code>custom:layout-card</code> (separate install)</td><td style="text-align:center;">✅ <code>lcards-layout-card</code>, <code>lcards-layout-view</code></td><td>LCARdS has its own grid layouts with visual editors. Replace <code>custom:layout-card</code> with <code>lcards-layout-card</code>: change the <code>type</code> and remove <code>layout_type</code>; the <code>layout</code> and <code>view_layout</code> keys stay the same. See <a href="./../cards/layout-card/">Layout Card</a>.</td></tr><tr><td>Select menu</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ <code>lcards-select-menu</code></td><td>A grid of buttons for an <code>input_select</code> or <code>select</code> entity.</td></tr><tr><td>card-mod</td><td style="text-align:center;">⚠️ required</td><td style="text-align:center;">✅ not needed</td><td>LCARdS needs no other custom cards or card-mod.</td></tr><tr><td>Charts / Graphs</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ <code>lcards-chart</code></td><td>Embedded ApexCharts library providing 15+ chart types to plot entity/data.</td></tr><tr><td>MSD (Master Systems Display)</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ <code>lcards-msd</code></td><td>Full MSD system in a card. Embed controls, connect routing lines, add animations to reflect statuses.</td></tr><tr><td>Background Animations</td><td style="text-align:center;">✅ GRID, ALERT, GEO Array, Pulsewave</td><td style="text-align:center;">⚠️ ✅</td><td>Background animations split into stackable layers: mix and match building blocks. ✅ GRID (enhanced), ✅ ALERT (button component), ✅ Starfield &amp; Nebula (enhanced). ⚠️ GEO Array, Pulsewave (pending).</td></tr><tr><td>Element Animations</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td>Embedded Anime.js v4 enabling animation of any SVG element (cards, lines/stroke, text, etc.).</td></tr><tr><td>Symbiont (embedded cards)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>Available in Elbow card: attempts native card injection for basic style imprinting. Add <code>card_mod</code> config for advanced styling.</td></tr><tr><td>State-based Styling / Custom States</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅✅</td><td>CB-LCARS has a limited set of states. LCARdS uses common state groupings (<code>default</code> | <code>active</code> | <code>inactive</code> | <code>unavailable</code>) plus the ability to define <em><strong>any state</strong></em> for customised styling. Integrates with the core rules engine for hot-patching.</td></tr><tr><td>Sounds</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td>Customisable sounds for many UI and card event types (tap, double tap, hold, hover, sidebar expand/collapse, and more).</td></tr><tr><td>Alert Overlay</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ <code>lcards-alert-overlay</code></td><td>Dashboard-level card that reacts to <code>input_select.lcards_alert_mode</code> and displays a full-screen configurable backdrop with an embedded content card.</td></tr></tbody></table>',8)])])}const b=e(r,[["render",c]]);export{m as __pageData,b as default};
